CREATE OR REPLACE FUNCTION pg_temp.cle(nom text) RETURNS text AS $fn$
  SELECT coalesce(string_agg(mot, ' ' ORDER BY ord), '')
  FROM (
    SELECT ord, CASE mot
             WHEN 'AV' THEN 'AVENUE' WHEN 'AVE' THEN 'AVENUE'
             WHEN 'BLD' THEN 'BOULEVARD' WHEN 'BVD' THEN 'BOULEVARD'
             WHEN 'BLVD' THEN 'BOULEVARD' WHEN 'BOULD' THEN 'BOULEVARD'
             WHEN 'IMP' THEN 'IMPASSE' WHEN 'RTE' THEN 'ROUTE' ELSE mot END AS mot
    FROM regexp_split_to_table(
           regexp_replace(upper(translate(nom,
             'ÀÁÂÃÄÅÇÈÉÊËÌÍÎÏÑÒÓÔÕÖÙÚÛÜÝàáâãäåçèéêëìíîïñòóôõöùúûüýÿ',
             'AAAAAACEEEEIIIINOOOOOUUUUYaaaaaaceeeeiiiinooooouuuuyy')),
             '[^A-Z0-9]+', ' ', 'g'), '\s+') WITH ORDINALITY AS t(mot, ord)
    WHERE mot <> '' AND mot NOT IN ('DE','DU','DES','LA','LE','LES','L','D')
  ) s;
$fn$ LANGUAGE sql IMMUTABLE;

CREATE TEMP TABLE voie AS
SELECT (f->'properties'->>'way_id')::bigint            AS way_id,
       nullif(f->'properties'->>'nom','')              AS nom,
       (f->'properties'->>'type_street')::varchar(20)  AS type_street,
       ST_Transform(ST_SetSRID(ST_GeomFromGeoJSON(f->'geometry'), 4326), 32638) AS g
FROM jsonb_array_elements((SELECT doc FROM osm_source)->'features') AS f;

UPDATE voie SET g = ST_CollectionExtract(
  ST_Intersection(g, ST_Transform((SELECT geom FROM public.contour_national LIMIT 1), 32638)), 2);
DELETE FROM voie WHERE g IS NULL OR ST_IsEmpty(g) OR ST_Length(g) < 10;
CREATE INDEX ON voie USING GIST (g);

CREATE TEMP TABLE rues AS
SELECT "Name", ST_Transform("Boundary", 32638) AS g FROM public."Streets" WHERE "Boundary" IS NOT NULL;
CREATE INDEX ON rues USING GIST (g);

CREATE TEMP TABLE reste AS
SELECT v.* FROM voie v
WHERE coalesce(ST_Length(ST_Intersection(v.g,
        (SELECT ST_Union(ST_Buffer(r.g, 20)) FROM rues r WHERE ST_DWithin(r.g, v.g, 20)))), 0)
      / NULLIF(ST_Length(v.g), 0) <= 0.7;
CREATE INDEX ON reste USING GIST (g);

CREATE TEMP TABLE nommees AS
SELECT pg_temp.cle(nom) AS cle,
       (array_agg(nom ORDER BY length(nom)))[1] AS nom,
       (array_agg(type_street ORDER BY type_street))[1] AS type_street,
       min(way_id) AS way_id,
       ST_Multi(ST_LineMerge(ST_Collect(ST_Transform(g, 4326)))) AS geom
FROM reste WHERE nom IS NOT NULL GROUP BY pg_temp.cle(nom);

-- ⚠️ `ST_Collect`, PAS `ST_Union`. `ST_Union` NŒUDE le réseau : il coupe chaque ligne à
-- toutes ses intersections avant de recoller, si bien que `ST_LineMerge` rend PLUS de morceaux
-- qu'il n'y avait de voies en entrée — 7 683 fragments pour 3 718 voies, mesuré le 2026-09-02.
-- C'est l'inverse du but recherché. `ST_Collect` se contente d'agréger, et `ST_LineMerge`
-- recolle alors les tronçons bout à bout en s'arrêtant d'elle-même aux carrefours, où le
-- raccord serait ambigu.
CREATE TEMP TABLE chaines AS
SELECT type_street, (ST_Dump(ST_LineMerge(ST_Collect(g)))).geom AS g
FROM reste WHERE nom IS NULL GROUP BY type_street;
CREATE INDEX ON chaines USING GIST (g);

-- Rattacher chaque chaîne à un `way_id` OSM, pour son `Code`.
--
-- ⚠️ La version précédente exigeait qu'un tronçon soit à 90 % dans la chaîne, puis SUPPRIMAIT
-- les chaînes sans candidat. Deux conséquences mesurées au test du 2026-09-02 : des voies
-- étaient jetées SANS message, et le second passage les réinsérait sous d'autres chaînes
-- (`INSERT 0 377` au rejeu). Un import qui perd des lignes en silence est pire qu'un import qui
-- échoue.
--
-- Le tronçon le PLUS PROCHE est donc retenu, sans seuil : une chaîne est faite de tronçons, il
-- y en a forcément un à distance nulle. `way_id` en second critère de tri rend le choix
-- déterministe quand plusieurs sont à égalité.
CREATE TEMP TABLE anonymes AS
SELECT c.type_street,
       (SELECT v.way_id FROM reste v
         WHERE v.nom IS NULL AND v.type_street = c.type_street
         ORDER BY ST_Distance(v.g, c.g), v.way_id LIMIT 1) AS way_id,
       ST_Multi(ST_Transform(c.g, 4326)) AS geom
FROM chaines c;

-- Deux chaînes peuvent retomber sur le même tronçon le plus proche. Sans suffixe, la seconde
-- porterait un `Code` déjà pris et le filet anti-collision l'écarterait — en silence, encore.
ALTER TABLE anonymes ADD COLUMN rang int;
UPDATE anonymes a SET rang = t.rang
FROM (SELECT ctid, row_number() OVER (PARTITION BY way_id ORDER BY ST_Length(geom::geography) DESC) AS rang
      FROM anonymes) t WHERE t.ctid = a.ctid;

CREATE TEMP TABLE a_inserer AS
SELECT left('OSM-' || replace(cle, ' ', '-'), 200) AS code, nom, type_street, geom FROM nommees n
WHERE NOT EXISTS (SELECT 1 FROM public."Streets" s WHERE pg_temp.cle(s."Name") = n.cle)
UNION ALL
SELECT 'OSM-W' || way_id || CASE WHEN rang > 1 THEN '-' || rang ELSE '' END,
       NULL, type_street, geom FROM anonymes;

CREATE TEMP TABLE rapport(ordre int, section text, detail text, valeur text);
INSERT INTO rapport
SELECT 1,'bilan','voies OSM du perimetre',count(*)::text FROM voie
UNION ALL SELECT 2,'bilan','deja couvertes par Streets',(SELECT count(*) FROM voie)::text
UNION ALL SELECT 3,'bilan','restantes',count(*)::text FROM reste
UNION ALL SELECT 4,'bilan','  nommees regroupees',count(*)::text FROM nommees
UNION ALL SELECT 5,'bilan','  anonymes apres fusion des chaines',count(*)::text FROM anonymes
UNION ALL SELECT 6,'bilan','A INSERER',count(*)::text FROM a_inserer;
UPDATE rapport SET valeur = ((SELECT count(*) FROM voie) - (SELECT count(*) FROM reste))::text WHERE ordre = 2;
INSERT INTO rapport
SELECT 7,'par type',type_street,count(*)||' voies, '||round(sum(ST_Length(geom::geography))/1000)||' km'
FROM a_inserer GROUP BY type_street;

-- Seules les écritures qui suivent sont dans la transaction.
BEGIN;

INSERT INTO public."Streets" ("Id", "Code", "Name", "Type", "Boundary")
SELECT gen_random_uuid(), a.code, a.nom, a.type_street, a.geom
FROM a_inserer a
-- Filet : un `Code` déjà pris ferait échouer tout le lot.
WHERE NOT EXISTS (SELECT 1 FROM public."Streets" s WHERE s."Code" = a.code);

-- Remplacer par ROLLBACK pour un essai à blanc.
COMMIT;

INSERT INTO rapport
SELECT 8, 'Streets apres ecriture', "Type", count(*) || ' lignes, ' || count("Boundary") || ' avec geometrie'
FROM public."Streets" GROUP BY "Type";

SELECT section, detail, valeur FROM rapport ORDER BY ordre, detail;
